"use client";

import { useEffect, useRef } from "react";
import createGlobe, { type Marker as CobeArcPoint } from "cobe";
import {
  AUTO_ROTATE_SPEED,
  GLOBE_RADIUS_RATIO,
  THETA,
  project,
} from "@/lib/globe-projection";

export type AvatarPoint = {
  id: string;
  lat: number;
  lng: number;
  avatar_url: string;
  label: string;
  isOrigin?: boolean;
};

export type GlobeTheme = "dark" | "light";

type ThemePalette = {
  dark: number;
  baseColor: [number, number, number];
  markerColor: [number, number, number];
  glowColor: [number, number, number];
  arcColor: [number, number, number];
  ring: string;
  ringOrigin: string;
};

const THEMES: Record<GlobeTheme, ThemePalette> = {
  dark: {
    dark: 1,
    baseColor: [0.16, 0.16, 0.17],
    markerColor: [0.9, 0.9, 0.9],
    glowColor: [0.35, 0.35, 0.38],
    arcColor: [0.8, 0.8, 0.8],
    ring: "ring-white/70",
    ringOrigin: "ring-white",
  },
  light: {
    dark: 0,
    baseColor: [0.92, 0.92, 0.94],
    markerColor: [0.1, 0.1, 0.12],
    glowColor: [0.75, 0.75, 0.8],
    arcColor: [0.2, 0.2, 0.22],
    ring: "ring-black/40",
    ringOrigin: "ring-black",
  },
};

type GlobeProps = {
  points: AvatarPoint[];
  /** Diameter of the globe in pixels. Defaults to 320. */
  size?: number;
  /** Color palette for the globe surface, markers, and avatar rings. Defaults to "dark". */
  theme?: GlobeTheme;
};

export function Globe({ points, size = 320, theme = "dark" }: GlobeProps) {
  const palette = THEMES[theme];
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const avatarRefs = useRef<Map<string, HTMLDivElement>>(new Map());
  const pointerInteracting = useRef<number | null>(null);
  const pointerInteractionMovement = useRef(0);
  const phi = useRef(0);
  const width = useRef(0);
  const pointsRef = useRef(points);

  useEffect(() => {
    pointsRef.current = points;
  }, [points]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    let frame: number;
    const isSmallScreen = window.innerWidth < 640;

    let resizeFrame: number | null = null;
    const onResize = () => {
      if (resizeFrame !== null) return;
      resizeFrame = requestAnimationFrame(() => {
        width.current = container.offsetWidth;
        resizeFrame = null;
      });
    };
    window.addEventListener("resize", onResize);
    onResize();

    const buildArcs = () => {
      const origin = pointsRef.current.find((p) => p.isOrigin);
      if (!origin) return [];
      return pointsRef.current
        .filter((p) => !p.isOrigin)
        .map((p) => ({
          from: [origin.lat, origin.lng] as [number, number],
          to: [p.lat, p.lng] as [number, number],
          color: [0.85, 0.85, 0.85] as [number, number, number],
        }));
    };

    const buildMarkers = (): CobeArcPoint[] =>
      pointsRef.current.map((p) => ({
        location: [p.lat, p.lng],
        size: p.isOrigin ? 0.045 : 0.02,
      }));

    const dpr = isSmallScreen ? 1.5 : 2;

    const globe = createGlobe(canvas, {
      devicePixelRatio: dpr,
      width: width.current * dpr,
      height: width.current * dpr,
      phi: 0,
      theta: THETA,
      dark: palette.dark,
      diffuse: 1.1,
      mapSamples: isSmallScreen ? 9000 : 17000,
      mapBrightness: 5,
      baseColor: palette.baseColor,
      markerColor: palette.markerColor,
      glowColor: palette.glowColor,
      arcColor: palette.arcColor,
      arcWidth: 0.55,
      arcHeight: 0.3,
      markers: buildMarkers(),
      arcs: buildArcs(),
    });

    const animate = () => {
      if (document.hidden) {
        frame = requestAnimationFrame(animate);
        return;
      }

      if (pointerInteracting.current === null) {
        phi.current += AUTO_ROTATE_SPEED;
      }
      globe.update({
        phi: phi.current,
        width: width.current * dpr,
        height: width.current * dpr,
        markers: buildMarkers(),
        arcs: buildArcs(),
      });

      const radius = width.current * GLOBE_RADIUS_RATIO;
      const centerX = width.current / 2;
      const centerY = width.current / 2;

      for (const p of pointsRef.current) {
        const el = avatarRefs.current.get(p.id);
        if (!el) continue;
        const { x, y, z } = project(p.lat, p.lng, phi.current, THETA, radius);
        if (z <= -0.15) {
          el.style.opacity = "0";
          el.style.pointerEvents = "none";
          continue;
        }
        const depth = Math.max(0, Math.min(1, (z + 0.15) / 1.15));
        const scale = 0.55 + depth * 0.55;
        el.style.opacity = String(0.35 + depth * 0.65);
        el.style.pointerEvents = "auto";
        el.style.zIndex = String(Math.round(depth * 100));
        el.style.transform = `translate3d(${centerX + x}px, ${centerY + y}px, 0) translate(-50%, -50%) scale(${scale})`;
      }

      frame = requestAnimationFrame(animate);
    };
    frame = requestAnimationFrame(animate);

    setTimeout(() => {
      canvas.style.opacity = "1";
    });

    return () => {
      cancelAnimationFrame(frame);
      if (resizeFrame !== null) cancelAnimationFrame(resizeFrame);
      globe.destroy();
      window.removeEventListener("resize", onResize);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- palette is derived from the theme prop, and a theme change should recreate the globe with fresh colors
  }, [theme]);

  return (
    <div
      ref={containerRef}
      className="relative mx-auto aspect-square w-full"
      style={{ maxWidth: size }}
    >
      <canvas
        ref={canvasRef}
        onPointerDown={(e) => {
          pointerInteracting.current =
            e.clientX - pointerInteractionMovement.current;
          if (canvasRef.current) canvasRef.current.style.cursor = "grabbing";
        }}
        onPointerUp={() => {
          pointerInteracting.current = null;
          if (canvasRef.current) canvasRef.current.style.cursor = "grab";
        }}
        onPointerOut={() => {
          pointerInteracting.current = null;
          if (canvasRef.current) canvasRef.current.style.cursor = "grab";
        }}
        onMouseMove={(e) => {
          if (pointerInteracting.current !== null) {
            const delta = e.clientX - pointerInteracting.current;
            pointerInteractionMovement.current = delta;
            phi.current = delta / 200;
          }
        }}
        onTouchMove={(e) => {
          if (pointerInteracting.current !== null && e.touches[0]) {
            const delta = e.touches[0].clientX - pointerInteracting.current;
            pointerInteractionMovement.current = delta;
            phi.current = delta / 100;
          }
        }}
        style={{
          width: "100%",
          height: "100%",
          cursor: "grab",
          opacity: 0,
          transition: "opacity 1s ease",
        }}
      />

      {points.map((p) => (
        <div
          key={p.id}
          ref={(el) => {
            if (el) avatarRefs.current.set(p.id, el);
            else avatarRefs.current.delete(p.id);
          }}
          title={p.label}
          className="pointer-events-none absolute left-0 top-0 will-change-transform"
          style={{ opacity: 0 }}
        >
          <div
            className={
              p.isOrigin
                ? `h-8 w-8 overflow-hidden rounded-full ring-2 ${palette.ringOrigin} sm:h-9 sm:w-9`
                : `h-5 w-5 overflow-hidden rounded-full ring-1 ${palette.ring} sm:h-6 sm:w-6`
            }
          >
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={p.avatar_url}
              alt={p.label}
              className="h-full w-full object-cover"
              draggable={false}
            />
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { Globe, type AvatarPoint, type GlobeTheme } from "@/components/globe";

type Marker = {
  login: string;
  name: string | null;
  avatar_url: string;
  location: string;
  lat: number;
  lng: number;
};

type ApiResponse = {
  origin: Marker | null;
  markers: Marker[];
  total: number;
  resolved: number;
  error?: string;
};

export type GitphereGlobeProps = {
  /** GitHub username whose following list gets mapped. */
  username: string;
  /** Diameter of the globe in pixels. Defaults to 320. */
  size?: number;
  /** Color palette for the globe. Defaults to "dark". */
  theme?: GlobeTheme;
  /**
   * Path to the installed API route that resolves following + locations.
   * Defaults to "/api/gitphere-following", the route this registry item installs alongside it.
   * Override only if you renamed the route or proxy it elsewhere.
   */
  endpoint?: string;
  className?: string;
};

export function GitphereGlobe({
  username,
  size = 320,
  theme = "dark",
  endpoint = "/api/gitphere-following",
  className,
}: GitphereGlobeProps) {
  const [data, setData] = useState<ApiResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    // eslint-disable-next-line react-hooks/set-state-in-effect -- intentional: resets loading/error state when username or endpoint changes, before kicking off the new fetch
    setLoading(true);
    setError(null);

    fetch(`${endpoint}?username=${encodeURIComponent(username)}`)
      .then(async (res) => {
        const json: ApiResponse = await res.json();
        if (!res.ok) throw new Error(json.error || "something went wrong");
        return json;
      })
      .then((json) => {
        if (!cancelled) setData(json);
      })
      .catch((err) => {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "something went wrong");
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [username, endpoint]);

  const points: AvatarPoint[] = useMemo(() => {
    if (!data) return [];
    const mapped: AvatarPoint[] = data.markers.map((m) => ({
      id: m.login,
      lat: m.lat,
      lng: m.lng,
      avatar_url: m.avatar_url,
      label: `${m.name || m.login} · ${m.location}`,
    }));
    if (data.origin) {
      mapped.push({
        id: data.origin.login,
        lat: data.origin.lat,
        lng: data.origin.lng,
        avatar_url: data.origin.avatar_url,
        label: `${data.origin.name || data.origin.login} · ${data.origin.location}`,
        isOrigin: true,
      });
    }
    return mapped;
  }, [data]);

  if (error) {
    return (
      <div className={className} style={{ maxWidth: size }} role="alert">
        <p className="text-sm text-neutral-500">
          couldn&apos;t load @{username}&apos;s globe: {error}
        </p>
      </div>
    );
  }

  if (loading) {
    return (
      <div
        className={className}
        style={{
          width: size,
          height: size,
          maxWidth: size,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
        aria-busy="true"
        aria-label={`loading @${username}'s following map`}
      >
        <p className="text-sm text-white/40 animate-pulse">
          mapping @{username}&apos;s network…
        </p>
      </div>
    );
  }

  return (
    <div className={className}>
      <Globe points={points} size={size} theme={theme} />
    </div>
  );
}

export const THETA = 0.32;
export const GLOBE_RADIUS_RATIO = 0.44; // fraction of canvas width used as sphere radius
export const AUTO_ROTATE_SPEED = 0.0022;

export function project(
  lat: number,
  lng: number,
  phi: number,
  theta: number,
  radius: number,
) {
  const latRad = (lat * Math.PI) / 180;
  const lonRad = (lng * Math.PI) / 180 - Math.PI;
  const cosLat = Math.cos(latRad);

  const x0 = -cosLat * Math.cos(lonRad);
  const y0 = Math.sin(latRad);
  const z0 = cosLat * Math.sin(lonRad);

  const cx = Math.cos(theta);
  const sx = Math.sin(theta);
  const cy = Math.cos(phi);
  const sy = Math.sin(phi);

  const x = cy * x0 + sy * z0;
  const y = sy * sx * x0 + cx * y0 - cy * sx * z0;
  const z = -sy * cx * x0 + sx * y0 + cy * cx * z0;

  return { x: x * radius, y: -y * radius, z };
}

export type GithubUser = {
  login: string;
  avatar_url: string;
  location: string | null;
  name: string | null;
  following: number;
};

function githubHeaders(userAgent: string): Record<string, string> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": userAgent,
  };
  if (process.env.GITHUB_TOKEN) {
    headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  }
  return headers;
}

function describeGithubError(res: Response): string {
  if (res.status === 404) {
    return "github user not found";
  }
  if (res.status === 403 || res.status === 429) {
    const remaining = res.headers.get("x-ratelimit-remaining");
    if (remaining === "0") {
      return process.env.GITHUB_TOKEN
        ? "github rate limit exceeded even with a token — try again in a few minutes"
        : "github rate limit exceeded (60 requests/hour without a token) — add a GITHUB_TOKEN env var to raise this limit, see the README";
    }
    return "github rejected the request (403) — check that your GITHUB_TOKEN, if set, is valid";
  }
  return `github lookup failed (${res.status})`;
}

/** Fetches a GitHub user, returning null on any failure (404, rate limit, network error). */
export async function fetchGithubUser(
  username: string,
  userAgent: string,
): Promise<GithubUser | null> {
  try {
    const res = await fetch(`https://api.github.com/users/${username}`, {
      headers: githubHeaders(userAgent),
      cache: "no-store",
    });
    if (!res.ok) return null;
    return res.json();
  } catch {
    return null;
  }
}

/** Fetches a GitHub user, throwing a descriptive error on failure (used where a missing user is fatal). */
export async function fetchGithubUserOrThrow(
  username: string,
  userAgent: string,
): Promise<GithubUser> {
  const res = await fetch(`https://api.github.com/users/${username}`, {
    headers: githubHeaders(userAgent),
    cache: "no-store",
  });
  if (!res.ok) {
    throw new Error(describeGithubError(res));
  }
  return res.json();
}

export async function fetchFollowing(
  username: string,
  userAgent: string,
): Promise<{ login: string; avatar_url: string }[]> {
  const res = await fetch(
    `https://api.github.com/users/${username}/following?per_page=100`,
    { headers: githubHeaders(userAgent), cache: "no-store" },
  );
  if (!res.ok) {
    throw new Error(describeGithubError(res));
  }
  return res.json();
}

import { NextRequest, NextResponse } from "next/server";
import {
  fetchFollowing,
  fetchGithubUser,
  fetchGithubUserOrThrow,
} from "@/lib/github";

// Sent to GitHub's API as the User-Agent header, required by their API.
// Change this to your own project name if you like — it has no effect on behavior.
const USER_AGENT = "gitphere-globe-widget";

type Marker = {
  login: string;
  name: string | null;
  avatar_url: string;
  location: string;
  lat: number;
  lng: number;
};

const geocodeCache = new Map<string, { lat: number; lng: number } | null>();

async function geocode(
  location: string,
): Promise<{ lat: number; lng: number } | null> {
  const key = location.trim().toLowerCase();
  if (geocodeCache.has(key)) {
    return geocodeCache.get(key) ?? null;
  }
  try {
    const res = await fetch(
      `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(
        location,
      )}`,
      // Nominatim's usage policy requires an identifying User-Agent — swap in your own
      // project name and, ideally, a contact (see https://operations.osmfoundation.org/policies/nominatim/).
      { headers: { "User-Agent": `${USER_AGENT} (personal project)` } },
    );
    if (!res.ok) {
      geocodeCache.set(key, null);
      return null;
    }
    const data = await res.json();
    if (!Array.isArray(data) || data.length === 0) {
      geocodeCache.set(key, null);
      return null;
    }
    const result = {
      lat: parseFloat(data[0].lat),
      lng: parseFloat(data[0].lon),
    };
    geocodeCache.set(key, result);
    return result;
  } catch {
    geocodeCache.set(key, null);
    return null;
  }
}

async function mapWithConcurrency<T, R>(
  items: T[],
  limit: number,
  fn: (item: T) => Promise<R>,
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let index = 0;
  async function worker() {
    while (index < items.length) {
      const current = index++;
      results[current] = await fn(items[current]);
    }
  }
  await Promise.all(Array.from({ length: limit }, worker));
  return results;
}

export async function GET(req: NextRequest) {
  const username = req.nextUrl.searchParams.get("username")?.trim();

  if (!username) {
    return NextResponse.json(
      { error: "username is required" },
      { status: 400 },
    );
  }

  try {
    const [originUser, following] = await Promise.all([
      fetchGithubUserOrThrow(username, USER_AGENT),
      fetchFollowing(username, USER_AGENT),
    ]);

    let origin: Marker | null = null;
    if (originUser.location) {
      const coords = await geocode(originUser.location);
      if (coords) {
        origin = {
          login: originUser.login,
          name: originUser.name,
          avatar_url: originUser.avatar_url,
          location: originUser.location,
          lat: coords.lat,
          lng: coords.lng,
        };
      }
    }

    if (following.length === 0) {
      return NextResponse.json({ origin, markers: [], total: 0, resolved: 0 });
    }

    const users = await mapWithConcurrency(following, 5, async (f) => {
      const user = await fetchGithubUser(f.login, USER_AGENT);
      return (
        user ?? {
          login: f.login,
          avatar_url: f.avatar_url,
          location: null,
          name: null,
          following: 0,
        }
      );
    });

    const withLocation = users.filter(
      (u): u is (typeof users)[number] & { location: string } =>
        !!u.location && u.location.trim().length > 0,
    );

    const markers = await mapWithConcurrency(withLocation, 3, async (u) => {
      const coords = await geocode(u.location);
      if (!coords) return null;
      const marker: Marker = {
        login: u.login,
        name: u.name,
        avatar_url: u.avatar_url,
        location: u.location,
        lat: coords.lat,
        lng: coords.lng,
      };
      return marker;
    });

    const resolved = markers.filter((m): m is Marker => m !== null);

    return NextResponse.json({
      origin,
      markers: resolved,
      total: following.length,
      resolved: resolved.length,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : "something went wrong";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
